MISSING = object()
def fresh():
    return object()
def missing(v=MISSING) -> bool:
    return v is MISSING
xs = [fresh() for i in range(128)]
ys = xs[:]
keys = {x: i for i, x in enumerate(xs)}
hashes = [hash(x) for x in xs]
xs.clear()
for j in range(64):
    noise = [fresh() for i in range(8)]
    assert all(x not in keys for x in noise)
assert len(keys) == 128
assert len(set(ys)) == 128
for i, x in enumerate(ys):
    assert keys[x] == i and hash(x) == hashes[i]
    assert type(x) is object and x.__class__.__module__ == "builtins"
    assert str(x) == repr(x) and repr(x).startswith("<object object at 0x")
    for k in range(len(ys)):
        assert (x is ys[k]) == (i == k)
for x in ys[:32]:
    del keys[x]
assert len(keys) == 96
print("identity", len(ys), len(keys), missing(), missing(None), missing(3), missing(False), missing("x"))

